// src/js/assetResolver.js
const ASSET_URLS = import.meta.glob('/src/img/**/*.{png,jpg,jpeg,webp,svg,gif}', {
  eager: true,
  import: 'default', // Using default import is often more reliable for URLs in Vite
});

export function assetUrl(relPath) {
  // 1. Clean the path (remove leading slashes or ./ )
  const normalized = String(relPath || '').replace(/^(\.\/|\/)/, ''); 
  
  // 2. Construct the key to match exactly how Vite sees it in the glob
  // It must start with /src/img/ to match the glob above
  const key = `/src/img/${normalized}`;
  
  const url = ASSET_URLS[key];

  if (!url) {
    console.warn(`[assetUrl] Not found: ${key}`);
    // Optional: Return the path as-is so the browser can try to resolve it normally
    return relPath; 
  }
  
  return url;
}